#include <Arduino.h>
#include <lvgl/lvgl.h>

#include "Config.h"
#include "PullStateManager.h"
#include "ScreenUpdater.h"
#include "SpeedModule.h"
#include "StateManager.h"
#include "dev_utils/benchmark.h"
#include "display/backlight.h"
#include "display/display.h"
#include "display/lvgl_callbacks.h"
#include "touch/touch.h"
#include "peripherals/PeripheralsInit.h"
#include "peripherals/touch_inject.h"

// UI generated by Squareline
#include "../ui/ui.h"

void setup() {
  Serial.begin(SERIAL_BAUD_RATE);
  delay(1000);
  PeripheralsInit();


  StateManager::loadPreferences();
  // Preferences prefs;
  // prefs.begin("touch_cal", false);
  // prefs.clear();  // ⚠️ This erases everything in "touch_cal"
  // prefs.end();

  Serial.println("Starting M4 7-inch RGB Display UI: M4_MCU_2025...");
  Serial.print("Version: ");
  Serial.println(DEVICE_VERSION);
  Serial.print("Build Date: ");
  Serial.println(__DATE__ " " __TIME__);

  // Initialize display first
  init_display();

  // Initialize touch hardware
  init_touch();

  init_lvgl();
  ui_init();
  touch_inject_init();
  
  // Apply saved screen rotation
  StateManager::setScreenRotation(StateManager::prefs().screenRotation180);
  
  PullStateManager::init();
  SpeedModule::begin();


  xTaskCreatePinnedToCore(lvgl_task, "lvgl_task", 4096, NULL, 1, NULL, 1);
  // setRecalibrationFlag();
  Serial.println("Setup complete");
}

bool isMainScreenReady() {
  return uic_MainLabelSpeedValue && uic_MainLabelDistanceValue && uic_MainLabelTachValue && uic_MainLabelDriverName &&
         uic_MainLabelDriverNumber && uic_MainLabelClassName;
}

unsigned long lastScreenUpdate = 0;

void loop() {
  PeripheralsPoll();
  lv_timer_handler();
  updateBacklight();
  benchmark_update();
  PullStateManager::update();
  SpeedModule::tick();

  unsigned long now = millis();
  if (isMainScreenReady() && now - lastScreenUpdate >= SCREEN_UPDATE_INTERVAL_MS) {
    lastScreenUpdate = now;
    updateMainScreen();
  }
  // TODO: look into removing this delay, if we need to slow down a task we should slow down the specific task.
  // This is just to prevent the loop from running too fast and hogging CPU time.
  // lv_timer_handler() should be enough to throttle the loop.
  delay(5);
}